// 判断是否满足要求
bool judge(vector<int>& ans, int personNum, int target, int index, vector<int>& load) {
    if (index < 0) {
        return true;
    }
    for (int i = 0; i < personNum; i++) {
        // 剪枝
        if (i > 0 && load[i] == load[i-1]) {
            continue;
        }
​
        // 递归回溯
        if (load[i] + ans[index] <= target) {
            load[i] += ans[index];
            if (judge(ans, personNum, target, index - 1, load)) {
                return true;
            }
            load[i] -= ans[index];
        }
        //剪枝：如果当前人是第一个任务都没分配过的，直接跳出，避免不必要尝试
        if (load[i] == 0) {
            break;
        }
    }
    return false;
}
