// 二分 + 递归回溯解决
int solve(vector<int>& ans, int personNum) {
    int sum = 0;
    int n = ans.size();
    for (int i = 0; i < n; i++) {
        sum += ans[i];
    }
    // 二分
    int left = 0, right = sum;
    while (left < right) {
        int target = (left + right) >> 1;
        vector<int> load(personNum, 0);
        if (judge(ans, personNum, target, n -1, load)) {
            right = target;
        } else {
            left = target + 1;
        }
    }
    return left;
}
