// 判断是否满足要求
func judge(ans []int, personNum int, target int, index int, load []int) bool {
    if index < 0 {
        return true
    }
    for i := 0; i < personNum; i++ {
        // 剪枝
        if i > 0 && load[i] == load[i-1] {
            continue
        }
        if load[i]+ans[index] <= target {
            load[i] += ans[index]
            if judge(ans, personNum, target, index-1, load) {
                return true
            }
            load[i] -= ans[index]
        }
        // 剪枝
        if load[i] == 0 {
            break
        }
    }
    return false
}
​
// 二分 + 递归回溯
func solve(ans []int, personNum int) int {
    left, right := 0, 0
    for _, v := range ans {
        right += v
    }
​
    for left < right {
        target := (left + right) / 2
        load := make([]int, personNum)
​
        if judge(ans, personNum, target, len(ans)-1, load) {
            right = target
        } else {
            left = target + 1
        }
    }
    return left
}
​
func main() {
    scanner := bufio.NewScanner(os.Stdin)
    scanner.Scan()
    s := scanner.Text()
    scanner.Scan()
    personNum, _ := strconv.Atoi(scanner.Text())
​
    nums := strings.Split(s, ",")
    ans := make([]int, len(nums))
    for i, num := range nums {
        ans[i], _ = strconv.Atoi(num)
    }
​
    // 从小到大排序
    sort.Ints(ans)
    fmt.Println(solve(ans, personNum))
}
